"""Regenerate _atlas/MESH_LIST.md from _atlas/hierarchy.json (the true Z-Anatomy parent tree)."""
import json, re
H = json.load(open("_atlas/hierarchy.json"))
L = ["# MESH_LIST: Z-Anatomy (Startup.blend, Blender 3.05), real hierarchy", "",
     "Generated by tools/atlas/build_meshlist.py from hierarchy.json (dump made by tools/atlas/dump_hierarchy.py in headless Blender 4.2).",
     "Supersedes the earlier keyword-based list: the true structure is the object-parent tree through hidden FONT objects named `*.g`;",
     "Blender collections are flat per body system (1: Skeletal ... 7: Nervous system & Sense organs ... 9: Regions).", "",
     "## Suffixes (decoded from the data)", ""]
for k, v in H["suffixes"].items(): L.append(f"- `{k}`: {v}")
L += ["", "## Collections", ""]
def ct(c, d=0):
    L.append("  " * d + f"- {c['collection']}: {c['objects']} objects, {c['geometry_objects']} with geometry")
    for x in c.get("children", []): ct(x, d + 1)
ct(H["collections"])
L += ["", f"## Exported to the atlas: {H['exported_structures']} structures (L/R pairs merged). `[x]` = exported, `[ ]` = not exported (v = vertices in source)", ""]
def gt(g, d=0):
    L.append("  " * d + f"- **{g['group']}**")
    seen = {}
    for o in g["objects"]:
        b = re.sub(r"\.[lr]$", "", o["name"]); seen.setdefault(b, []).append(o)
    for b, os_ in seen.items():
        sides = "/".join(x["name"][-1] for x in os_ if re.search(r"\.[lr]$", x["name"])) or "mid"
        L.append("  " * (d + 1) + f"- [{'x' if any(x['exported'] for x in os_) else ' '}] {b} ({os_[0]['type'].lower()}, {sides}, v={os_[0]['verts']})")
    for c in g["children"]: gt(c, d + 1)
gt(H["nervous_system_groups"])
for g in H["cardiovascular_groups_cerebral"]: gt(g)
if H.get("meninges_group"): gt(H["meninges_group"])
L += ["", "## Known gaps (no mesh of their own in Z-Anatomy)", "",
      "Substantia nigra, periaqueductal grey, medial lemniscus, MLF, dentate nucleus, internal capsule, pineal gland, middle/inferior cerebellar peduncles (as separate objects), subthalamic nucleus, nucleus accumbens, brainstem sensory nuclei other than cochlear/vestibular (solitary, spinal trigeminal, gracile/cuneate nuclei), cerebellar nuclei, anterior/posterior spinal arteries. See UNMATCHED.md for the fallbacks used.", ""]
open("_atlas/MESH_LIST.md", "w", encoding="utf-8").write("\n".join(L))
